import { createContext } from "svelte";
import type { HTMLAttributes, HTMLInputAttributes } from "svelte/elements";
import type { OTPValidationType } from "./otp-field-machine.js";

export interface OTPFieldContext {
  readonly activeIndex: number;
  readonly ariaInvalid: HTMLAttributes<HTMLDivElement>["aria-invalid"];
  readonly autocomplete: HTMLInputAttributes["autocomplete"];
  readonly disabled: boolean;
  readonly id: string;
  readonly inputMode: "decimal" | "email" | "none" | "numeric" | "search" | "tel" | "text" | "url";
  readonly length: number;
  readonly mask: boolean;
  readonly readonly: boolean;
  readonly validationType: OTPValidationType;
  clear(event: KeyboardEvent): void;
  createSlot(): OTPFieldSlot;
  delete(slot: OTPFieldSlot, backward: boolean, event: KeyboardEvent): void;
  focus(index: number): void;
  indexOf(slot: OTPFieldSlot): number;
  input(raw: string, slot: OTPFieldSlot, event: InputEvent | Event): void;
  paste(raw: string, slot: OTPFieldSlot, event: ClipboardEvent): void;
  register(slot: OTPFieldSlot, input: HTMLInputElement | null): void;
  unregister(slot: OTPFieldSlot): void;
  valueAt(slot: OTPFieldSlot): string;
}

export interface OTPFieldSlot {
  readonly key: symbol;
  element: HTMLInputElement | null;
}

export const [getOTPFieldContext, setOTPFieldContext] = createContext<OTPFieldContext>();

export type OTPValidationType = "alpha" | "alphanumeric" | "none" | "numeric";

export function normalizeOTP(value: string, validationType: OTPValidationType): string {
  const stripped = value.replace(/\s/g, "");
  if (validationType === "none") return stripped;
  if (validationType === "numeric") return stripped.replace(/[^0-9]/g, "");
  if (validationType === "alpha") return stripped.replace(/[^A-Za-z]/g, "");
  return stripped.replace(/[^A-Za-z0-9]/g, "");
}

export function normalizeOTPValueWithDetails(
  value: string | null | undefined,
  length: number,
  validationType: OTPValidationType,
  normalizeValue?: (value: string) => string,
): readonly [value: string, didRejectCharacters: boolean] {
  const raw = value ?? "";
  const stripped = raw.replace(/\s/g, "");
  let normalized = normalizeOTP(stripped, validationType);
  let didRejectCharacters = raw.length > stripped.length || stripped.length > normalized.length;

  if (normalizeValue) {
    const customNormalized = normalizeValue(normalized);
    didRejectCharacters ||= normalized.length > customNormalized.length;
    normalized = normalizeOTP(customNormalized, validationType);
    didRejectCharacters ||= customNormalized.length > normalized.length;
  }

  const characters = Array.from(normalized);
  const clamped = characters.slice(0, Math.max(0, length)).join("");
  return [clamped, didRejectCharacters || characters.length > Math.max(0, length)];
}

export function normalizeOTPValue(
  value: string | null | undefined,
  length: number,
  validationType: OTPValidationType,
  normalizeValue?: (value: string) => string,
): string {
  return normalizeOTPValueWithDetails(value, length, validationType, normalizeValue)[0];
}

export function replaceOTPRange(
  current: string,
  insertion: string,
  index: number,
  length: number,
): string {
  const slots = Array.from({ length }, (_, slot) => current[slot] ?? "");
  for (const [offset, character] of Array.from(insertion).entries()) {
    if (index + offset >= length) break;
    slots[index + offset] = character;
  }
  return slots.join("");
}

export type { OTPFieldInputProps } from "./otp-field-input.svelte";
export { default as Input, default as OTPFieldInput } from "./otp-field-input.svelte";
export { normalizeOTP, type OTPValidationType, replaceOTPRange } from "./otp-field-machine.js";
export type {
  OTPFieldChangeEventDetails,
  OTPFieldChangeReason,
  OTPFieldCompleteEventDetails,
  OTPFieldCompleteReason,
  OTPFieldEventForReason,
  OTPFieldInvalidEventDetails,
  OTPFieldInvalidReason,
  OTPFieldRootProps,
  OTPFieldSize,
} from "./otp-field-root.svelte";
export { default as OTPField, default as Root } from "./otp-field-root.svelte";
export type { OTPFieldSeparatorProps } from "./otp-field-separator.svelte";
export { default as OTPFieldSeparator, default as Separator } from "./otp-field-separator.svelte";
